export interface LeadCapture {
  leadCaptureId: number;
  companyId?: number; // Optional for public create, but expected for internal operations
  fullName: string;
  email: string;
  companyName?: string;
  phone?: string;
  jobTitle?: string;
  message?: string;
  leadSource: string;
  interestArea?: string;
  status: string;
  assignedTo?: number;
  privacyConsentAccepted: boolean;
  created_At: string;
  updated_at?: string;
}

export interface LeadCaptureListResponse {
  leadCaptures: LeadCapture[];
}

// For public create endpoint, omit companyId, leadCaptureId, status, assignedTo, created_At, updated_at
export interface CreateLeadCaptureRequest {
  fullName: string;
  email: string;
  companyName?: string;
  phone?: string;
  jobTitle?: string;
  message?: string;
  leadSource: string;
  interestArea?: string;
  privacyConsentAccepted: boolean;
}

export interface UpdateLeadCaptureRequest {
  leadCaptureId: number;
  companyId: number; // Required for internal update ops
  fullName?: string;
  email?: string;
  companyName?: string;
  phone?: string;
  jobTitle?: string;
  message?: string;
  leadSource?: string;
  interestArea?: string;
  status?: string;
  assignedTo?: number;
  privacyConsentAccepted?: boolean;
}

// GET ALL — POST /all_leadCaptures
export async function getAllLeadCaptures(companyId: number): Promise<LeadCapture[]> {
  const res = await fetch(BASE_URL + "/all_leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: LeadCaptureListResponse = await res.json();
  return data.leadCaptures ?? [];
}

// CREATE — action: 1
// ADR-001: Public submission endpoint must not read, accept, default, or validate against a client-supplied companyId.
// ADR-002: Treat a response with an embedded error or duplicate indication as a failure even when HTTP status is 200.
export async function createLeadCapture(payload: CreateLeadCaptureRequest): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    // Omit internal-only fields like companyId, status, assignedTo, created_At, updated_at for public create
    body: JSON.stringify({ "leadCaptures": [{ "action": 1, ...payload }] }),
  });
  // Even if res.ok is true, check for embedded errors as per ADR-002
  const result = await res.json();
  if (!res.ok || result.error) {
    throw new Error(result.error || "Error creando lead");
  }
  return result;
}

// UPDATE — action: 2
// ADR-002: Treat a response with an embedded error or duplicate indication as a failure even when HTTP status is 200.
export async function updateLeadCapture(payload: UpdateLeadCaptureRequest): Promise<LeadCapture> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 2, ...payload }] }),
  });
  // Even if res.ok is true, check for embedded errors as per ADR-002
  const result = await res.json();
  if (!res.ok || result.error) {
    throw new Error(result.error || "Error actualizando lead");
  }
  return result;
}

// DELETE — action: 3
export async function deleteLeadCapture(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/leadCaptures", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "leadCaptures": [{ "action": 3, "leadCaptureId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
