  IonSelect,
  IonSelectOption,
  IonLoading,
  IonToast,
  IonAlert,
  IonInfiniteScroll,
  IonInfiniteScrollContent,
  IonSearchbar,
  IonCard,
  IonCardContent,
  IonChip,,
  InputInputEventDetail,
  SearchbarInputEventDetail,
  SelectChangeEventDetail,
  TextareaChangeEventDetail
} from '@ionic/react';
import { add, create, trash, close, save, search, chevronDown } from 'ionicons/icons';
import { useIonViewWillEnter } from '@ionic/react';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../components/UserContext';
import {
  LeadCapture,
  getAllLeadCaptures,
  createLeadCapture,
  updateLeadCapture,
  deleteLeadCapture,
  CreateLeadCaptureRequest,
  UpdateLeadCaptureRequest,
} from '../api/leadCaptureApi';

import './LeadCapturePage.css';

// UTC-7 offset conversion for Hermosillo
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours for UTC-7
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

// IVA is always 0, as per mandatory constraint.
const IVA = 0;

const LEAD_STATUS_OPTIONS = [
  { value: 'New', label: 'Nuevo', color: 'primary' },
  { value: 'Contacted', label: 'Contactado', color: 'warning' },
  { value: 'Qualified', label: 'Calificado', color: 'tertiary' },
  { value: 'Converted', label: 'Convertido', color: 'success' },
  { value: 'Disqualified', label: 'Descalificado', color: 'medium' },
];

const LEAD_SOURCE_OPTIONS = [
  { value: 'Website', label: 'Sitio Web' },
  { value: 'Referral', label: 'Referencia' },
  { value: 'Social Media', label: 'Red Social' },
  { value: 'Campaign', label: 'Campaña' },
  { value: 'Other', label: 'Otro' },
];

const INTEREST_AREA_OPTIONS = [
  { value: 'New Product', label: 'Nuevo Producto' },
  { value: 'Pricing', label: 'Precios' },
  { value: 'Demo Request', label: 'Solicitud de Demostración' },
  { value: 'Support', label: 'Soporte' },
  { value: 'Partnership', label: 'Asociación' },
];

const LeadCapturePage: React.FC = () => {
  const { companyId } = useUser();
  const [leads, setLeads] = useState<LeadCapture[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [leadToEdit, setLeadToEdit] = useState<LeadCapture | null>(null);
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [leadToDeleteId, setLeadToDeleteId] = useState<number | null>(null);

  const [newLead, setNewLead] = useState<Partial<CreateLeadCaptureRequest>>({
    fullName: '',
    email: '',
    leadSource: 'Website',
    privacyConsentAccepted: false,
  });

  const [editLead, setEditLead] = useState<Partial<UpdateLeadCaptureRequest>>({});

  const [searchText, setSearchText] = useState('');
  const [filterStatus, setFilterStatus] = useState<string[]>([]);
  const [filterInterestArea, setFilterInterestArea] = useState<string[]>([]);

  // Popover state for Header component
  const [popoverState, setPopoverState] = useState({
    showAlertPopover: false,
    showMailPopover: false,
    event: undefined as Event | undefined,
  });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  // Pagination for infinite scroll
  const [page, setPage] = useState(0);
  const [hasMoreItems, setHasMoreItems] = useState(true);
  const PAGE_SIZE = 20;

  const fetchLeads = async (initialLoad: boolean = true) => {
    if (initialLoad) {
      setLoading(true);
      setPage(0);
      setHasMoreItems(true);
    }
    if (!companyId) {
      setError('Company ID is not available.');
      setLoading(false);
      return;
    }

    try {
      const allLeads = await getAllLeadCaptures(companyId);
      // Apply filters here, as the backend only supports companyId for getAll
      const filteredLeads = allLeads.filter(lead => {
        const matchesSearch = searchText === '' ||
          lead.fullName.toLowerCase().includes(searchText.toLowerCase()) ||
          lead.email.toLowerCase().includes(searchText.toLowerCase()) ||
          lead.companyName?.toLowerCase().includes(searchText.toLowerCase());
        const matchesStatus = filterStatus.length === 0 || filterStatus.includes(lead.status);
        const matchesInterestArea = filterInterestArea.length === 0 || (lead.interestArea && filterInterestArea.includes(lead.interestArea));
        return matchesSearch && matchesStatus && matchesInterestArea;
      }).sort((a, b) => new Date(b.created_At).getTime() - new Date(a.created_At).getTime()); // Newest first

      if (initialLoad) {
        setLeads(filteredLeads.slice(0, PAGE_SIZE));
        setHasMoreItems(filteredLeads.length > PAGE_SIZE);
      } else {
        const newItems = filteredLeads.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
        setLeads(prev => [...prev, ...newItems]);
        setHasMoreItems(filteredLeads.length > (page + 1) * PAGE_SIZE);
      }
      setPage(prev => prev + 1);
    } catch (err) {
      setError((err as Error).message ?? 'Error cargando prospectos');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchLeads(true);
  });

  useEffect(() => {
    fetchLeads(true);
  }, [searchText, filterStatus, filterInterestArea, companyId]);

  const loadMoreItems = () => {
    fetchLeads(false);
  };

  const handleCreateLead = async () => {
    if (!newLead.fullName || !newLead.email || !newLead.leadSource || !newLead.privacyConsentAccepted) {
      setError('Por favor, complete todos los campos obligatorios y acepte la política de privacidad.');
      return;
    }
    setSaving(true);
    setError(null);
    try {
      await createLeadCapture(newLead as CreateLeadCaptureRequest);
      setShowCreateModal(false);
      setNewLead({
        fullName: '',
        email: '',
        leadSource: 'Website',
        privacyConsentAccepted: false,
      });
      fetchLeads(true); // Refetch all leads to include the new one
    } catch (err) {
      setError((err as Error).message ?? 'Error al crear el prospecto');
    } finally {
      setSaving(false);
    }
  };

  const handleEditClick = (lead: LeadCapture) => {
    setLeadToEdit(lead);
    setEditLead({ ...lead }); // Populate form with existing data
    setShowEditModal(true);
  };

  const handleUpdateLead = async () => {
    if (!editLead.leadCaptureId || !companyId) {
      setError('ID de prospecto o de compañía no disponible para actualizar.');
      return;
    }
    setSaving(true);
    setError(null);
    try {
      await updateLeadCapture(editLead as UpdateLeadCaptureRequest);
      setShowEditModal(false);
      setLeadToEdit(null);
      setEditLead({});
      fetchLeads(true); // Refetch all leads
    } catch (err) {
      setError((err as Error).message ?? 'Error al actualizar el prospecto');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (id: number) => {
    setLeadToDeleteId(id);
    setShowDeleteAlert(true);
  };

  const confirmDeleteLead = async () => {
    if (!leadToDeleteId || !companyId) return;
    setLoading(true);
    setError(null);
    try {
      await deleteLeadCapture(leadToDeleteId, companyId);
      fetchLeads(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar el prospecto');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: string) => {
    const statusOption = LEAD_STATUS_OPTIONS.find(opt => opt.value === status);
    return statusOption ? statusOption.color : 'medium'; // Default to medium if not found
  };

  return (
    <IonPage className="lead-capture-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Captura de Prospectos — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonLoading isOpen={loading} message="Cargando prospectos..." />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError(null)}
          color="danger"
        />

        <div className="lead-capture-filter-container">
          <IonSearchbar
            value={searchText}
            onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
            placeholder="Buscar prospectos..."
            debounce={300}
            fill="outline"
            className="lead-capture-searchbar"
          />
          <IonItem fill="outline" className="lead-capture-filter-item">
            <IonLabel position="floating">Estado</IonLabel>
            <IonSelect
              value={filterStatus}
              multiple={true}
              onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFilterStatus(e.detail.value)}
              toggleIcon={chevronDown}
              interface="popover"
              placeholder="Filtrar por estado"
            >
              {LEAD_STATUS_OPTIONS.map(option => (
                <IonSelectOption key={option.value} value={option.value}>
                  {option.label}
                </IonSelectOption>
              ))}
            </IonSelect>
          </IonItem>
          <IonItem fill="outline" className="lead-capture-filter-item">
            <IonLabel position="floating">Área de Interés</IonLabel>
            <IonSelect
              value={filterInterestArea}
              multiple={true}
              onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFilterInterestArea(e.detail.value)}
              toggleIcon={chevronDown}
              interface="popover"
              placeholder="Filtrar por área de interés"
            >
              {INTEREST_AREA_OPTIONS.map(option => (
                <IonSelectOption key={option.value} value={option.value}>
                  {option.label}
                </IonSelectOption>
              ))}
            </IonSelect>
          </IonItem>
        </div>

        <IonList className="lead-capture-list">
          {leads.length === 0 && !loading && (
            <IonItem>
              <IonLabel>No hay prospectos para mostrar.</IonLabel>
            </IonItem>
          )}
          {leads.map((lead) => (
            <IonCard key={lead.leadCaptureId} className="lead-capture-card">
              <IonCardContent>
                <div className="lead-capture-card-header">
                  <IonLabel className="lead-capture-full-name">{lead.fullName}</IonLabel>
                  <IonChip className="status-chip" color={getStatusColor(lead.status)}>{LEAD_STATUS_OPTIONS.find(opt => opt.value === lead.status)?.label || lead.status}</IonChip>
                </div>
                <IonLabel className="lead-capture-email">{lead.email}</IonLabel>
                {lead.companyName && <IonLabel className="lead-capture-company">{lead.companyName}</IonLabel>}
                <div className="lead-capture-metadata">
                  <IonChip>{LEAD_SOURCE_OPTIONS.find(opt => opt.value === lead.leadSource)?.label || lead.leadSource}</IonChip>
                  {lead.interestArea && <IonChip>{INTEREST_AREA_OPTIONS.find(opt => opt.value === lead.interestArea)?.label || lead.interestArea}</IonChip>}
                </div>
                <IonLabel className="lead-capture-date">Creado: {toHermosillo(lead.created_At)}</IonLabel>
                {lead.updated_at && <IonLabel className="lead-capture-date">Actualizado: {toHermosillo(lead.updated_at)}</IonLabel>}
                <div className="lead-capture-actions">
                  <IonButton fill="clear" color="primary" onClick={() => handleEditClick(lead)}>
                    <IonIcon icon={create} slot="icon-only" />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={() => handleDeleteClick(lead.leadCaptureId)}>
                    <IonIcon icon={trash} slot="icon-only" />
                  </IonButton>
                </div>
              </IonCardContent>
            </IonCard>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={(ev: CustomEvent<void>) => {
          if (hasMoreItems) {
            loadMoreItems();
          }
          (ev.target as HTMLIonInfiniteScrollElement).complete();
        }} disabled={!hasMoreItems || loading}>
          <IonInfiniteScrollContent loadingText="Cargando más prospectos..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={() => setShowCreateModal(true)}>
            <IonIcon icon={add} />
          </IonFabButton>
        </IonFab>

        {/* Create Lead Modal */}
        <IonModal isOpen={showCreateModal} onDidDismiss={() => setShowCreateModal(false)}>
          <IonHeader>
            <IonToolbar>
              <IonTitle>Nuevo Prospecto</IonTitle>
              <IonButton slot="end" fill="clear" onClick={() => setShowCreateModal(false)}>
                <IonIcon icon={close} />
              </IonButton>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <form onSubmit={(e) => {
              e.preventDefault();
              handleCreateLead();
            }}>
