                    fill="outline"
                    label="Nombre Completo *"
                    labelPlacement="floating"
                    value={newLead.fullName}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLead(p => ({ ...p, fullName: e.detail.value! }))}
                    required
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Email *"
                    labelPlacement="floating"
                    type="email"
                    value={newLead.email}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLead(p => ({ ...p, email: e.detail.value! }))}
                    required
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Nombre de la Compañía"
                    labelPlacement="floating"
                    value={newLead.companyName}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLead(p => ({ ...p, companyName: e.detail.value! }))}
                  />
                </div>
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Teléfono"
                    labelPlacement="floating"
                    type="tel"
                    value={newLead.phone}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setNewLead(p => ({ ...p, phone: e.detail.value! }))}
                  />
